#pragma once

#include <cstdint>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

struct DiscoveredPrinter
{
    std::string stable_id;
    std::string name;
    std::string ip_address;
    std::string device_model_id;
    std::string connection;
    bool connected{false};
};

struct PrinterEvidence
{
    std::string description;
    std::string image_bytes;
    std::string image_mime;
    std::string image_name;
    std::optional<DiscoveredPrinter> discovered_device;
};

struct PrinterCandidate
{
    // Opaque, session-local identifier exposed to the recognition provider.
    std::string id;
    std::string vendor_id;
    std::string vendor_name;
    std::string model_id;
    std::string model_name;
    std::string device_model_id;
    std::string variant;
    std::string preset_name;
    std::string build_volume;
    std::string default_material;
    std::string default_plate;
    std::string artwork_path;
};

enum class RecognitionDisposition { Recognized, Ambiguous, NoMatch };

struct RecognitionResult
{
    RecognitionDisposition disposition{RecognitionDisposition::NoMatch};
    std::vector<std::string> candidate_ids;
    std::string evidence_summary;
    std::string assumption;
};

struct RecognitionError
{
    std::string code;
    std::string message;
    bool retryable{false};
};

struct RecognitionEvent
{
    std::uint64_t generation{0};
    std::optional<RecognitionResult> result;
    std::optional<RecognitionError> error;
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#pragma once

#include "PrinterCatalog.hpp"
#include "PrinterRecognition.hpp"

#include <functional>
#include <memory>
#include <optional>
#include <set>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

enum class FlowState { Initial, Recognizing, Recognized, Ambiguous, Error, Complete };

class PrinterSetupController
{
public:
    using ApplyFn = std::function<bool(const PrinterCandidate&, std::string&)>;

    PrinterSetupController(PrinterCatalog catalog, std::unique_ptr<IPrinterRecognitionService> recognition,
                           ApplyFn apply);
    ~PrinterSetupController();

    FlowState state() const { return m_state; }
    const PrinterEvidence& evidence() const { return m_evidence; }
    const std::vector<const PrinterCandidate*>& candidates() const { return m_candidates; }
    const std::string& evidence_summary() const { return m_evidence_summary; }
    const std::string& assumption() const { return m_assumption; }
    const std::string& error() const { return m_error; }
    bool retryable() const { return m_retryable; }
    const PrinterCatalog& catalog() const { return m_catalog; }

    bool recognize(PrinterEvidence evidence);
    void poll();
    bool use_discovered(const DiscoveredPrinter& printer);
    bool choose(const std::string& candidate_id);
    bool confirm();
    void start_over();

private:
    void accept(const RecognitionEvent& event);

    PrinterCatalog m_catalog;
    std::unique_ptr<IPrinterRecognitionService> m_recognition;
    ApplyFn m_apply;
    FlowState m_state{FlowState::Initial};
    PrinterEvidence m_evidence;
    std::vector<const PrinterCandidate*> m_candidates;
    std::set<std::string> m_allowed_candidate_ids;
    std::string m_evidence_summary;
    std::string m_assumption;
    std::string m_error;
    bool m_retryable{false};
    std::uint64_t m_generation{0};
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#include "PrinterSetupController.hpp"

#include <algorithm>
#include <set>
#include <utility>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

PrinterSetupController::PrinterSetupController(PrinterCatalog catalog,
                                               std::unique_ptr<IPrinterRecognitionService> recognition,
                                               ApplyFn apply)
    : m_catalog(std::move(catalog)), m_recognition(std::move(recognition)), m_apply(std::move(apply)) {}

PrinterSetupController::~PrinterSetupController()
{
    if (m_recognition) m_recognition->cancel();
}

bool PrinterSetupController::recognize(PrinterEvidence evidence)
{
    if (evidence.description.empty() && evidence.image_bytes.empty()) return false;
    m_evidence = std::move(evidence);
    m_candidates.clear();
    m_error.clear();
    m_retryable = false;
    ++m_generation;
    const auto choices = m_catalog.recognition_choices(m_evidence);
    m_allowed_candidate_ids.clear();
    for (const PrinterCandidate* choice : choices)
        if (choice) m_allowed_candidate_ids.insert(choice->id);
    if (!m_recognition || !m_recognition->ready()) {
        m_state = FlowState::Error;
        m_error = "Printer recognition needs the OpenAI key configured in the Agent panel. You can still use a network printer or set it up manually.";
        return false;
    }
    if (!m_recognition->start(m_generation, m_evidence, choices)) {
        m_state = FlowState::Error;
        m_error = "Printer recognition could not start.";
        m_retryable = true;
        return false;
    }
    m_state = FlowState::Recognizing;
    return true;
}

void PrinterSetupController::poll()
{
    if (!m_recognition) return;
    while (auto event = m_recognition->poll()) accept(*event);
}

void PrinterSetupController::accept(const RecognitionEvent& event)
{
    if (event.generation != m_generation || m_state != FlowState::Recognizing) return;
    if (event.error) {
        m_state = FlowState::Error;
        m_error = event.error->message;
        m_retryable = event.error->retryable;
        return;
    }
    if (!event.result) return;
    std::set<std::string> seen;
    for (const std::string& id : event.result->candidate_ids) {
        if (!seen.insert(id).second) continue;
        if (!m_allowed_candidate_ids.count(id)) continue;
        if (const PrinterCandidate* candidate = m_catalog.find(id)) m_candidates.push_back(candidate);
    }
    m_evidence_summary = event.result->evidence_summary;
    m_assumption = event.result->assumption;
    if (event.result->disposition == RecognitionDisposition::Recognized && m_candidates.size() == 1)
        m_state = FlowState::Recognized;
    else if (event.result->disposition == RecognitionDisposition::Ambiguous && m_candidates.size() >= 2)
        m_state = FlowState::Ambiguous;
    else {
        m_state = FlowState::Error;
        m_error = "That evidence did not match a supported printer profile. Add a clearer description or photo, or set it up manually.";
    }
}

bool PrinterSetupController::use_discovered(const DiscoveredPrinter& printer)
{
    const PrinterCandidate* candidate = m_catalog.find_device_model(printer.device_model_id);
    if (!candidate) {
        m_state = FlowState::Error;
        m_error = "The network printer was found, but its model does not match a supported local profile.";
        return false;
    }
    if (m_recognition) m_recognition->cancel();
    ++m_generation;
    m_evidence = {};
    m_evidence.discovered_device = printer;
    m_allowed_candidate_ids.clear();
    m_candidates = {candidate};
    m_evidence_summary = printer.name;
    m_assumption = printer.connection.empty() ? "Found on the local network."
                                               : "Connected · " + printer.connection;
    m_state = FlowState::Recognized;
    return true;
}

bool PrinterSetupController::choose(const std::string& candidate_id)
{
    if (m_state != FlowState::Ambiguous) return false;
    const auto found = std::find_if(m_candidates.begin(), m_candidates.end(), [&](const PrinterCandidate* candidate) {
        return candidate && candidate->id == candidate_id;
    });
    if (found == m_candidates.end()) return false;
    const PrinterCandidate* candidate = *found;
    m_candidates = {candidate};
    m_state = FlowState::Recognized;
    return true;
}

bool PrinterSetupController::confirm()
{
    if (m_state != FlowState::Recognized || m_candidates.size() != 1 || !m_apply) return false;
    std::string error;
    if (!m_apply(*m_candidates.front(), error)) {
        m_error = error.empty() ? "The printer setup could not be applied. Your previous setup is unchanged." : error;
        m_state = FlowState::Error;
        m_retryable = true;
        return false;
    }
    m_state = FlowState::Complete;
    return true;
}

void PrinterSetupController::start_over()
{
    if (m_recognition) m_recognition->cancel();
    ++m_generation;
    m_state = FlowState::Initial;
    m_evidence = {};
    m_candidates.clear();
    m_allowed_candidate_ids.clear();
    m_evidence_summary.clear();
    m_assumption.clear();
    m_error.clear();
    m_retryable = false;
}

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
