259	{
260	    wxWindowUpdateLocker lock(this);
261	    m_description = nullptr;
262	    m_description_is_prompt = false;
263	    m_root->Clear(true);
264	    const auto& metrics = m_theme.metrics();
265	    auto* content = new wxBoxSizer(wxVERTICAL);
266	    build_header(*content);
267	    int target_height = metrics.printer_setup.initial_height;
268	    switch (m_controller->state()) {
269	    case FlowState::Initial: build_initial(*content); break;
270	    case FlowState::Recognizing: build_recognizing(*content); break;
271	    case FlowState::Recognized:
272	        target_height = m_controller->evidence().discovered_device
273	            ? metrics.printer_setup.network_height
274	            : metrics.printer_setup.recognized_height;
275	        build_recognized(*content);
276	        break;
277	    case FlowState::Ambiguous:
278	        target_height = metrics.printer_setup.ambiguous_height;
279	        build_ambiguous(*content);
280	        break;
281	    case FlowState::Error: build_error(*content); break;
282	    case FlowState::Complete: EndModal(wxID_OK); return;
283	    }
284	    m_root->Add(content, 1, wxEXPAND | wxALL, FromDIP(metrics.space_6));
285	    Layout();
286	    Fit();
287	    const int fitted_height = GetClientSize().y;
288	    SetClientSize(wxSize(FromDIP(metrics.printer_setup.dialog_width),
289	                         std::max(FromDIP(target_height), fitted_height)));
290	    CentreOnParent();
291	}
