430	wxPanel* PrinterSetupDialog::candidate_card(wxWindow* parent, const PrinterCandidate& candidate, bool compact,
431	                                            const wxString& action, std::function<void()> invoke)
432	{
433	    const auto& metrics = m_theme.metrics();
434	    const int card_height = compact
435	        ? metrics.printer_setup.ambiguous_artwork_height + metrics.space_12 + metrics.space_10
436	        : metrics.printer_setup.candidate_min_height;
437	    auto* card = new RoundedPanel(parent,
438	                                  compact ? m_palette.surface_canvas : m_palette.surface_subtle,
439	                                  metrics.printer_setup.radius,
440	                                  wxSize(-1, parent->FromDIP(card_height)),
441	                                  compact ? m_palette.border_subtle : wxTransparentColour);
442	
443	    auto artwork = [&](wxWindow* artwork_parent, int size) -> wxWindow* {
444	        auto* holder = new RoundedPanel(artwork_parent, m_palette.surface_selected,
445	                                        metrics.printer_setup.control_radius,
446	                                        artwork_parent->FromDIP(wxSize(size, size)));
447	        if (!candidate.artwork_path.empty()) {
448	            wxImage image(wxString::FromUTF8(candidate.artwork_path));
449	            if (image.IsOk()) {
450	                const int pixels = holder->FromDIP(size);
451	                image.Rescale(pixels, pixels, wxIMAGE_QUALITY_HIGH);
452	                auto* holder_sizer = new wxBoxSizer(wxVERTICAL);
453	                holder_sizer->Add(new wxStaticBitmap(holder, wxID_ANY, wxBitmap(image)), 1,
454	                                  wxALIGN_CENTER | wxALL, holder->FromDIP(metrics.space_1));
455	                holder->SetSizer(holder_sizer);
456	            }
457	        }
458	        return holder;
459	    };
460	
461	    if (compact) {
462	        auto* column = new wxBoxSizer(wxVERTICAL);
463	        auto* art = artwork(card, metrics.printer_setup.ambiguous_artwork_height);
464	        art->SetMinSize(wxSize(-1, card->FromDIP(metrics.printer_setup.ambiguous_artwork_height)));
465	        column->Add(art, 0, wxEXPAND | wxBOTTOM, card->FromDIP(metrics.space_3));
466	        column->Add(label(card, wxString::FromUTF8(candidate.model_name), TextRole::BodyBold,
467	                          m_palette.text_primary), 0, wxBOTTOM, card->FromDIP(metrics.space_2));
468	        if (!action.empty())
469	            column->Add(button(card, action, false, std::move(invoke)), 0, wxALIGN_LEFT);
470	        auto* outer = new wxBoxSizer(wxVERTICAL);
471	        outer->Add(column, 1, wxEXPAND | wxALL, card->FromDIP(metrics.space_3));
472	        card->SetSizer(outer);
473	    } else {
474	        auto* row = new wxBoxSizer(wxHORIZONTAL);
475	        row->Add(artwork(card, metrics.printer_setup.artwork_size), 0,
476	                 wxALIGN_CENTER_VERTICAL | wxRIGHT, card->FromDIP(metrics.space_4));
477	        auto* details = new wxBoxSizer(wxVERTICAL);
478	        details->AddStretchSpacer();
479	        details->Add(label(card, wxString::FromUTF8(candidate.model_name), TextRole::Section,
480	                           m_palette.text_primary), 0, wxBOTTOM, card->FromDIP(metrics.space_1));
481	        if (!candidate.build_volume.empty())
482	            details->Add(label(card, wxString::FromUTF8(candidate.build_volume), TextRole::BodySmall,
483	                               m_palette.text_secondary));
484	        details->AddStretchSpacer();
485	        row->Add(details, 1, wxEXPAND);
486	        auto* outer = new wxBoxSizer(wxVERTICAL);
487	        outer->Add(row, 1, wxEXPAND | wxALL, card->FromDIP(metrics.space_3));
488	        card->SetSizer(outer);
489	    }
490	    return card;
