496	    const PrinterCandidate& candidate = *m_controller->candidates().front();
497	    if (const auto& device = m_controller->evidence().discovered_device; device) {
498	        const wxString connection = device->connection.empty() ? _L("LOCAL") : uppercase_ascii(device->connection);
499	        content.Add(label(this, wxString::Format(_L("●  Connected · %s"), connection),
