505	    }
506	    content.Add(candidate_card(this, candidate, false, {}, {}), 0, wxEXPAND | wxBOTTOM, FromDIP(metrics.space_4));
507	    const wxString material = candidate.default_material.empty() ? _L("PLA")
508	                                                                  : display_material(candidate.default_material);
