530	    content.AddStretchSpacer();
531	    auto* actions = new wxBoxSizer(wxHORIZONTAL);
532	    actions->Add(link(this, _L("Not this one"), [this] { m_controller->start_over(); rebuild_later(); }),
533	                 0, wxALIGN_CENTER_VERTICAL);
534	    actions->AddStretchSpacer();
535	    auto* confirm = button(this, _L("＋  Add this printer"), true, [this, correction] {
536	        const std::string value(correction->GetValue().ToUTF8());
537	        if (!value.empty()) {
538	            m_draft = m_controller->evidence();
539	            m_draft.description += "\nCorrection: " + value;
540	            m_controller->recognize(m_draft);
541	            if (m_controller->state() == FlowState::Recognizing) m_timer.Start(50);
542	            rebuild_later();
543	        } else if (m_controller->confirm()) {
544	            EndModal(wxID_OK);
545	        } else {
546	            rebuild_later();
