632	bool PrinterSetupDialog::load_photo(const wxString& path)
633	{
634	    const std::string mime = mime_for(path);
635	    if (mime.empty()) {
636	        m_photo_error = _L("Choose a PNG, JPEG, or WebP image.");
637	        return false;
638	    }
639	    std::ifstream input(std::string(path.ToUTF8()), std::ios::binary);
640	    if (!input) {
641	        m_photo_error = _L("That photo could not be read. Choose another file.");
642	        return false;
643	    }
644	    std::string bytes((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
645	    if (bytes.empty()) {
646	        m_photo_error = _L("That photo is empty. Choose another file.");
647	        return false;
648	    }
649	    if (bytes.size() > kMaximumPhotoBytes) {
650	        m_photo_error = _L("That photo is larger than 10 MB. Choose a smaller image.");
651	        return false;
652	    }
653	    wxMemoryInputStream stream(bytes.data(), bytes.size());
654	    wxImage decoded(stream);
655	    if (!decoded.IsOk()) {
656	        m_photo_error = _L("That file is not a readable image. Choose another photo.");
657	        return false;
658	    }
659	    m_draft.image_bytes = std::move(bytes);
660	    m_draft.image_mime = mime;
661	    m_draft.image_name = std::string(wxFileName(path).GetFullName().ToUTF8());
662	    m_photo_error.clear();
663	    return true;
664	}
