717	class ModalScrim
718	{
719	public:
720	    ModalScrim(wxWindow* owner, const ShellPalette& palette, int alpha)
721	    {
722	        if (!owner) return;
723	        m_window = new wxFrame(owner, wxID_ANY, {}, wxDefaultPosition, wxDefaultSize,
724	                               wxFRAME_NO_TASKBAR | wxBORDER_NONE);
725	        if (!m_window->CanSetTransparent()) {
726	            m_window->Destroy();
727	            m_window = nullptr;
728	            return;
729	        }
730	        m_window->SetBackgroundColour(palette.overlay_scrim);
731	        m_window->SetSize(owner->GetScreenRect());
732	        m_window->SetTransparent(alpha);
733	        m_window->Show();
734	    }
735	
736	    ~ModalScrim()
737	    {
738	        if (m_window) {
739	            m_window->Hide();
740	            m_window->Destroy();
741	        }
742	    }
743	
744	    wxWindow* owner_or(wxWindow* fallback) const { return m_window ? m_window : fallback; }
745	
746	private:
747	    wxFrame* m_window{nullptr};
748	};
