752	void show_printer_setup(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater)
753	{
754	    PrinterCatalog catalog = PrinterCatalog::load(Slic3r::resources_dir());
755	    const bool use_mock = std::getenv("JUSPRIN_PRINTER_RECOGNITION_MOCK") != nullptr;
756	    OpenAIPrinterRecognitionConfig config;
757	    if (!use_mock && wxGetApp().app_config) {
758	        const std::string consent = wxGetApp().app_config->get("jusprin_agent", "cloud_consent");
759	        if (consent == "true" || consent == "1")
760	            config.api_key = Agent::load_provider_api_key("openai");
761	        const std::string model = wxGetApp().app_config->get("jusprin_agent", "model");
762	        if (!model.empty()) config.model = model;
763	    }
764	    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint && *endpoint)
765	        config.endpoint = endpoint;
766	    std::unique_ptr<IPrinterRecognitionService> recognition;
767	    if (use_mock)
768	        recognition = std::make_unique<DeterministicPrinterRecognition>();
769	    else
770	        recognition = std::make_unique<OpenAIPrinterRecognition>(std::move(config),
771	                                                                  Agent::make_openai_http_transport());
772	    auto apply = [&plater](const PrinterCandidate& candidate, std::string& error) {
773	        return SetupCommands::install_and_select_printer(plater, candidate.vendor_id, candidate.model_id,
774	                                                         candidate.variant, candidate.default_material, error);
775	    };
776	    auto controller = std::make_unique<PrinterSetupController>(std::move(catalog), std::move(recognition),
777	                                                                std::move(apply));
778	    std::vector<DiscoveredPrinter> discovered = discover_printers();
779	    // Explicit developer scenarios make every handed-off Figma state
780	    // inspectable in an isolated app without a live API request or hardware.
781	    if (use_mock) {
782	        const std::string scenario = std::getenv("JUSPRIN_PRINTER_SETUP_SCENARIO")
783	            ? std::getenv("JUSPRIN_PRINTER_SETUP_SCENARIO") : "";
784	        if (scenario == "recognized" || scenario == "ambiguous") {
785	            PrinterEvidence evidence;
786	            evidence.description = scenario == "recognized"
787	                ? "Bambu Lab A1 mini" : "the ender with the touchscreen";
788	            controller->recognize(std::move(evidence));
789	            controller->poll();
790	        } else if (scenario == "network") {
791	            discovered = {{"01P00A3B", "Bambu Lab A1 mini", "192.0.2.2", "N1", "LAN", true}};
792	            controller->use_discovered(discovered.front());
793	        }
794	    }
795	    ModalScrim scrim(owner, theme.palette(dark), theme.metrics().printer_setup.scrim_alpha);
796	    PrinterSetupDialog dialog(scrim.owner_or(owner), theme, dark, std::move(controller), std::move(discovered));
797	    dialog.ShowModal();
798	}
799	
800	void show_printer_setup(wxWindow* owner, bool dark, Plater& plater)
801	{
802	    try {
803	        const ShellTheme theme = ShellTheme::load_from_resources();
804	        show_printer_setup(owner, theme, dark, plater);
805	    } catch (const std::exception&) {
806	        // Theme/catalog packaging failures cannot be recovered inside the
807	        // custom flow; Orca's existing complete setup remains available.
808	        wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS);
809	    }
810	}
