152	+bool install_and_select_printer(Plater& plater, const std::string& vendor_id,
153	+                                const std::string& model_id, const std::string& variant,
154	+                                const std::string& default_filament, std::string& error)
155	+{
156	+    PresetBundle* presets = wxGetApp().preset_bundle;
157	+    AppConfig* config = wxGetApp().app_config;
158	+    if (!presets || !config || vendor_id.empty() || model_id.empty() || variant.empty()) {
159	+        error = "Printer setup is unavailable because the preset system is not ready.";
160	+        return false;
161	+    }
162	+    const auto old_vendors = config->vendors();
163	+    const bool had_filaments = config->has_section(AppConfig::SECTION_FILAMENTS);
164	+    const auto old_filaments = had_filaments ? config->get_section(AppConfig::SECTION_FILAMENTS)
165	+                                             : std::map<std::string, std::string>();
166	+    const std::string old_printer = presets->printers.get_selected_preset_name();
167	+    auto rollback = [&]() -> std::string {
168	+        config->set_vendors(old_vendors);
169	+        config->set_section(AppConfig::SECTION_FILAMENTS, old_filaments);
170	+        try {
171	+            presets->load_presets(*config, ForwardCompatibilitySubstitutionRule::Enable,
172	+                                  {std::string(), std::string(), std::string(), std::string()});
173	+            if (!select_printer_preset(plater, old_printer))
174	+                return "The previous printer preset could not be selected again.";
175	+            if (wxGetApp().mainframe) wxGetApp().mainframe->update_side_preset_ui();
176	+        } catch (const std::exception& exception) {
177	+            return std::string("The previous preset configuration could not be reloaded: ") + exception.what();
178	+        }
179	+        return {};
180	+    };
181	+    try {
182	+        std::map<std::string, std::map<std::string, std::set<std::string>>> vendors;
183	+        vendors[vendor_id][model_id].insert(variant);
184	+        std::map<std::string, std::string> filaments;
185	+        if (!default_filament.empty()) filaments[default_filament] = "true";
186	+        bool applied = false;
187	+        bool selected = false;
188	+        plater.update_objects_position_when_select_preset([&] {
189	+            applied = presets->apply_vendor_config(vendors, filaments, config, false, model_id, variant,
190	+                                                   default_filament);
191	+            if (!applied) return;
192	+            const Preset* preset = presets->printers.find_system_preset_by_model_and_variant(model_id, variant);
193	+            Tab* tab = wxGetApp().get_tab(Preset::TYPE_PRINTER);
194	+            if (!preset || !tab) return;
195	+            tab->select_preset(preset->name);
196	+            plater.on_config_change(presets->full_config());
197	+            selected = true;
198	+        });
199	+        if (!applied) {
200	+            const std::string rollback_error = rollback();
201	+            error = rollback_error.empty()
202	+                ? "The printer profile could not be installed. Your previous setup is unchanged."
203	+                : "The printer profile could not be installed. " + rollback_error;
204	+            return false;
205	+        }
206	+        if (!selected) {
207	+            const std::string rollback_error = rollback();
208	+            error = rollback_error.empty()
209	+                ? "The installed profile could not be selected. Your previous setup is unchanged."
210	+                : "The installed profile could not be selected. " + rollback_error;
211	+            return false;
212	+        }
213	+        if (wxGetApp().mainframe) wxGetApp().mainframe->update_side_preset_ui();
214	+        presets->export_selections(*config);
215	+        return true;
216	+    } catch (const std::exception& exception) {
217	+        const std::string rollback_error = rollback();
218	+        error = std::string("The printer profile could not be loaded: ") + exception.what();
219	+        if (!rollback_error.empty()) error += " " + rollback_error;
220	+        return false;
221	+    }
222	+}
