541	{
542	    std::set<std::string> result;
543	    std::string word;
544	    for (unsigned char c : lower(value)) {
545	        if (std::isalnum(c)) word.push_back(char(c));
546	        else if (word.size() > 1) { result.insert(word); word.clear(); }
547	        else word.clear();
548	    }
