561	json resolve_machine(const std::string& name, const std::map<std::string, json>& machines,
562	                     std::set<std::string>& visiting)
563	{
564	    const auto found = machines.find(name);
565	    if (found == machines.end() || !visiting.insert(name).second)
566	        return json::object();
567	    json resolved = json::object();
568	    const std::string parent = found->second.value("inherits", "");
569	    if (!parent.empty())
570	        resolved = resolve_machine(parent, machines, visiting);
571	    for (const auto& item : found->second.items())
572	        resolved[item.key()] = item.value();
573	    visiting.erase(name);
574	    return resolved;
575	}
