577	std::string build_volume(const json& machine)
578	{
579	    const auto area = machine.value("printable_area", json::array());
580	    double min_x = 0., min_y = 0., max_x = 0., max_y = 0.;
581	    bool first = true;
582	    for (const auto& point : area) {
583	        if (!point.is_string()) continue;
584	        const auto values = split(point.get<std::string>(), 'x');
585	        if (values.size() != 2) continue;
586	        try {
587	            const double x = std::stod(values[0]);
588	            const double y = std::stod(values[1]);
589	            if (first) { min_x = max_x = x; min_y = max_y = y; first = false; }
590	            else { min_x = std::min(min_x, x); max_x = std::max(max_x, x);
591	                   min_y = std::min(min_y, y); max_y = std::max(max_y, y); }
592	        } catch (const std::exception&) {}
593	    }
594	    if (first) return {};
595	    const std::string height = first_string(machine.value("printable_height", json()));
596	    if (height.empty()) return {};
597	    auto clean = [](double value) {
598	        std::ostringstream out;
599	        out << std::fixed << std::setprecision(value == std::floor(value) ? 0 : 1) << value;
600	        return out.str();
601	    };
602	    return clean(max_x - min_x) + " × " + clean(max_y - min_y) + " × " + height + " mm";
603	}
