609	PrinterCatalog PrinterCatalog::load(const std::string& resources_directory)
610	{
611	    const fs::path profiles = fs::path(resources_directory) / "profiles";
612	    std::vector<PrinterCandidate> candidates;
613	    for (const fs::directory_entry& vendor_entry : fs::directory_iterator(profiles)) {
614	        if (!vendor_entry.is_regular_file() || vendor_entry.path().extension() != ".json") continue;
615	        const std::string vendor_id = vendor_entry.path().stem().string();
616	        const json index = read_json(vendor_entry.path());
617	        if (!index.contains("machine_model_list") || !index.contains("machine_list")) continue;
618	        const std::string vendor_name = index.value("name", vendor_id);
619	        const fs::path vendor_dir = profiles / vendor_id;
620	
621	        std::map<std::string, json> machines;
622	        for (const auto& entry : index["machine_list"]) {
623	            const std::string name = entry.value("name", "");
624	            const std::string sub_path = entry.value("sub_path", "");
625	            if (!name.empty() && !sub_path.empty()) machines.emplace(name, read_json(vendor_dir / sub_path));
626	        }
627	
628	        for (const auto& entry : index["machine_model_list"]) {
629	            const std::string sub_path = entry.value("sub_path", "");
630	            if (sub_path.empty()) continue;
631	            const json model = read_json(vendor_dir / sub_path);
632	            const std::string model_name = model.value("name", entry.value("name", ""));
633	            const std::string model_id = model_name;
634	            const std::string device_model = model.value("model_id", "");
635	            const auto variants = split(first_string(model.value("nozzle_diameter", json())), ';');
636	            const auto materials = split(first_string(model.value("default_materials", json())), ';');
637	            const std::string plate = first_string(model.value("default_bed_type", json()));
638	            fs::path artwork = vendor_dir / (model_name + "_cover.png");
639	            if (!fs::exists(artwork)) artwork.clear();
640	
641	            for (const std::string& variant : variants) {
642	                const std::string preset_name = model_name + " " + variant + " nozzle";
643	                std::set<std::string> visiting;
644	                const json machine = resolve_machine(preset_name, machines, visiting);
645	                if (machine.empty()) continue; // not an installable variant
646	                PrinterCandidate candidate;
647	                candidate.id = "printer-" + std::to_string(candidates.size());
648	                candidate.vendor_id = vendor_id;
649	                candidate.vendor_name = vendor_name;
650	                candidate.model_id = model_id;
651	                candidate.model_name = model_name;
652	                candidate.device_model_id = device_model;
653	                candidate.variant = variant;
654	                candidate.preset_name = preset_name;
655	                candidate.build_volume = build_volume(machine);
656	                candidate.default_material = !materials.empty() ? materials.front()
657	                    : first_string(machine.value("default_filament_profile", json()));
658	                candidate.default_plate = plate;
659	                candidate.artwork_path = artwork.string();
660	                candidates.push_back(std::move(candidate));
661	            }
662	        }
663	    }
664	    if (candidates.empty())
665	        throw std::runtime_error("No installable printer profiles were found.");
666	    return PrinterCatalog(std::move(candidates));
667	}
