688	std::vector<const PrinterCandidate*> PrinterCatalog::recognition_choices(const PrinterEvidence& evidence) const
689	{
690	    struct Scored { const PrinterCandidate* candidate; int score; };
691	    const auto evidence_words = words(evidence.description);
692	    std::vector<Scored> scored;
693	    scored.reserve(m_candidates.size());
694	    for (const PrinterCandidate& candidate : m_candidates) {
695	        int score = 0;
696	        const auto candidate_words = words(candidate.vendor_name + " " + candidate.model_name + " " + candidate.variant);
697	        for (const std::string& word : evidence_words)
698	            if (candidate_words.count(word)) score += word.size() >= 4 ? 3 : 1;
699	        if (!evidence.description.empty() && lower(evidence.description).find(lower(candidate.model_name)) != std::string::npos)
700	            score += 20;
701	        scored.push_back({&candidate, score});
702	    }
703	    std::stable_sort(scored.begin(), scored.end(), [](const Scored& a, const Scored& b) { return a.score > b.score; });
704	
705	    std::vector<const PrinterCandidate*> result;
706	    std::set<std::string> models;
707	    const bool has_text_match = !scored.empty() && scored.front().score > 0;
708	    for (const Scored& item : scored) {
709	        if (has_text_match) {
710	            if (item.score == 0 || result.size() >= 60) break;
711	            result.push_back(item.candidate);
712	        } else if (models.insert(item.candidate->vendor_id + "\n" + item.candidate->model_id).second) {
713	            result.push_back(item.candidate);
714	            if (result.size() >= 400) break;
715	        }
716	    }
717	    return result;
718	}
