3065	// The argument the parent sent, as the bytes it sent.
3066	//
3067	// run_mcp_setup_command hands wxExecute a wide argv built with
3068	// wxString::FromUTF8, so Windows receives the argument intact -- but the CRT
3069	// then builds this process's narrow argv by converting that command line to
3070	// the ANSI code page, where the fixture literal's CJK has no representation
3071	// and is replaced before main is even entered. Nothing the parent does can
3072	// prevent that. Windows keeps the real command line in UTF-16, so read the
3073	// argument from there and re-encode it as the UTF-8 the parent will search
3074	// the output for. Off Windows the narrow argv already carries those bytes.
3075	std::string utf8_argument(int index, char** argv)
3076	{
3077	#ifdef _WIN32
3078	    int count = 0;
3079	    wchar_t** wide = ::CommandLineToArgvW(::GetCommandLineW(), &count);
3080	    if (wide == nullptr) return argv[index];
3081	    std::string text;
3082	    if (index < count) {
3083	        const int bytes = ::WideCharToMultiByte(CP_UTF8, 0, wide[index], -1, nullptr, 0, nullptr, nullptr);
3084	        if (bytes > 1) {
3085	            text.resize(std::size_t(bytes) - 1);
3086	            ::WideCharToMultiByte(CP_UTF8, 0, wide[index], -1, text.data(), bytes, nullptr, nullptr);
3087	        }
3088	    }
3089	    ::LocalFree(wide);
3090	    return text;
3091	#else
3092	    return argv[index];
3093	#endif
3094	}
